package com.ateliercampus.dao;
import com.ateliercampus.model.Etudiant;import java.sql.*;
public class EtudiantDao {public Etudiant findByEmail(String email)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT id,nom,email,role FROM Etudiant WHERE LOWER(email)=LOWER(?)")){p.setString(1,email);try(ResultSet r=p.executeQuery()){if(!r.next())return null;Etudiant e=new Etudiant(r.getLong("id"),r.getString("nom"),r.getString("email"));e.setRole(r.getString("role"));return e;}}}public String passwordHash(String email)throws SQLException{try(Connection c=Database.getConnection();PreparedStatement p=c.prepareStatement("SELECT mot_de_passe FROM Etudiant WHERE LOWER(email)=LOWER(?)")){p.setString(1,email);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):null;}}}}
